def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]

    if denominator == 0:
        return None

    result = numerator / denominator

    return {
        "value": result,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "ratio"
            }
        }
    }
